function syncTypedSelection(){const input=$('#ownText'),button=$('#askTypedText');if(button)button.disabled=!input||input.selectionEnd<=input.selectionStart;}
function askTypedSelection(){const input=$('#ownText');if(!input)return;const text=input.value.slice(input.selectionStart,input.selectionEnd).trim();if(!text){A.notify('先选中你想提问的一段文字。');return}A.page.focus=text;A.page.lastQuestion={text,audioId:A.audioId,time:A.audioTime()};A.save();openMirror({question:text,auto:true});}
function onRecordingState(active){document.body.classList.toggle('class-is-recording',active);const badge=$('#mirrorRecordingBadge');if(badge)badge.hidden=!active;if($('#classFlowState'))$('#classFlowState').textContent=active?'录音持续中':'录音记录';}
function onRecordingTick(time){if(A?.recording&&$('#mirrorRecordingBadge time'))$('#mirrorRecordingBadge time').textContent=A.fmt(time);}
function showSourceWhileRecording(index){const s=A.lecture[index];if(!s)return;if(!$('#mirrorDialog').open)openMirror();addBubble('teacher',`示例讲解原文 ${A.fmt(s.time)}：${s.zh}。你的课程录音仍在继续；结束录音后可以回听当前课堂声音。`);onRecordingState(true);}
function cameraPoint(p,W,H){const video=$('#handVideo'),vw=video.videoWidth||1280,vh=video.videoHeight||720,scale=Math.max(W/vw,H/vh);return{x:(1-p.x)*vw*scale+(W-vw*scale)/2,y:p.y*vh*scale+(H-vh*scale)/2};}
function onHandFrame(hands){if(!arMode)return false;const p=window.ClimateGlobe.onHands(hands),wrap=$('#sceneCanvas').getBoundingClientRect();if(!p){if(performance.now()-arLastSeen>650){$('#arHandGuide').hidden=false;$('#cameraStatus').textContent='未找到手掌 · 请把托举手放回画面';}return true}const pts=[5,9,13,17].map(i=>cameraPoint(p[i],wrap.width,wrap.height)),a=pts[0],b=pts[3],width=Math.hypot(a.x-b.x,a.y-b.y),R=Math.max(30,Math.min(Math.min(wrap.width,wrap.height)*.28,width*.95))*zoom;arTarget={cx:pts.reduce((s,p)=>s+p.x,0)/4,cy:pts.reduce((s,p)=>s+p.y,0)/4-R*.86,R};arLastSeen=performance.now();if(!arPose)arPose={...arTarget};$('#arHandGuide').hidden=true;$('#cameraStatus').textContent=window.ClimateGlobe.status();return true;}
function earthPose(W,H){if(!arMode)return{R:Math.min(W*.32,H*.36)*zoom,cx:W*.5,cy:H*.49};if(!arTarget||performance.now()-arLastSeen>650)return null;return arPose||arTarget;}
function arLoop(t){if(!arMode||!$('#labDialog').open)return;if(arTarget&&arPose){for(const k of ['cx','cy','R'])arPose[k]+=(arTarget[k]-arPose[k])*.23;}if(t-arLastDraw>28){if(performance.now()-arLastSeen>650)$('#arHandGuide').hidden=false;A.drawScene();arLastDraw=t;}arFrame=requestAnimationFrame(arLoop);}
function onCameraState(active){if(!A)return;const next=active&&A.lab==='earth',wrap=$('#labDialog .scene-wrap');window.ClimateGlobe?.onCameraState(next);wrap.classList.toggle('earth-mode',A.lab==='earth');wrap.classList.toggle('ar-camera',next);if($('#arLiveBadge'))$('#arLiveBadge').hidden=!next;if($('#arFullScreen'))$('#arFullScreen').hidden=!next;if($('#arSaveNotice'))$('#arSaveNotice').hidden=!next;if(next!==arMode){arMode=next;arTarget=null;arPose=null;arLastSeen=0;cancelAnimationFrame(arFrame);if(next){$('#arHandGuide').hidden=false;arFrame=requestAnimationFrame(arLoop);}else{$('#arHandGuide').hidden=true;wrap.classList.remove('ar-expanded');if(document.fullscreenElement===wrap)document.exitFullscreen().catch(()=>{});}}if(A.lab==='earth'){$('#cameraButton').textContent=active?'◎ 关闭摄像头叠加':'◎ 摄像头叠加到掌心';if($('#arStartButton'))$('#arStartButton').textContent=active?'◎ 关闭摄像头叠加':'◎ 开启摄像头 · 双手探索';}A.drawScene();}
function drawCameraCover(ctx,W,H){const video=$('#handVideo');if(!video.videoWidth)return;const scale=Math.max(W/video.videoWidth,H/video.videoHeight),w=video.videoWidth*scale,h=video.videoHeight*scale;ctx.save();ctx.translate(W,0);ctx.scale(-1,1);ctx.drawImage(video,(W-w)/2,(H-h)/2,w,h);ctx.restore();}
async function toggleARFullscreen(){const wrap=$('#labDialog .scene-wrap');if(document.fullscreenElement===wrap){await document.exitFullscreen();return}if(wrap.classList.contains('ar-expanded')){wrap.classList.remove('ar-expanded');return}try{if(!wrap.requestFullscreen)throw Error('unsupported');await wrap.requestFullscreen();}catch{wrap.classList.add('ar-expanded');}A.drawScene();}
