 if(/停止.*(讲|说)|别讲|安静/.test(q)){stopSpeaking();return}
 if(/(停止|结束).*录音/.test(q)){A.stopMic();closeVoice();return}
 if(/(开始|启动).*录音/.test(q)){closeVoice();A.startMic();return}
 if(/magic|升级.*笔记|整理.*笔记|增强.*笔记/i.test(q)){closeVoice();if($('#mirrorDialog').open)$('#mirrorDialog').close();await upgrade();return}
 if(/地球|earth|全球变暖/i.test(q)&&!/为什么|如何|什么是|怎么/.test(q)){toolOpen('earth');A.notify('地球已打开。可以继续说：看看北极、切换到2024年、显示手部骨骼。');brief('数据地球已经准备好了。一只手托住，另一只手捏合转动。你可以说，看看北极。');return}
 if(/pca.*(模型|实验)|打开.*(降维|坐标|投影)|三维坐标/i.test(q)){toolOpen('pca');return}
