 if(/旋转|转起来|转慢|转快/.test(q)&&$('#labDialog').open){rotateSpeed=/慢/.test(q)?.003:/快/.test(q)?.02:.008;cancelAnimationFrame(autoFrame);autoFrame=requestAnimationFrame(rotateLoop);return}
 if(/向左|左转|向右|右转|向上|向下/.test(q)&&$('#labDialog').open){A.setRotation(A.yaw+(/左/.test(q)?-.25:/右/.test(q)?.25:0),A.pitch+(/上/.test(q)?-.15:/下/.test(q)?.15:0));return}
 if(/放大|缩小/.test(q)&&$('#labDialog').open){zoom=Math.max(.65,Math.min(1.5,zoom+(/放大/.test(q)?.12:-.12)));A.drawScene();return}
