function exportNote(){const c=document.createElement('canvas');c.style.cssText='position:fixed;left:-3000px;width:900px;height:560px';document.body.appendChild(c);A.paintNote(c,true);const ink=c.toDataURL('image/png');c.remove();const p=A.page,enhanced=p.magic?enhancedHTML(p.magic).replace(/<button[^>]*>(.*?)<\/button>/gs,'<span>$1</span>'):'';const cards=p.cards.map(x=>`<article><small>${x.type==='clip'?'视频片段引用':x.type==='lab'?'工具观察':'笔记补充'}</small><h3>${e(x.title)}</h3>${x.image?`<img src="${x.image}" alt="保存的模型视图">`:''}<p>${e(x.text||x.reason||'')}</p>${x.type==='clip'?`<p>${A.fmt(x.start)}–${A.fmt(x.end)}</p>${x.local?'<small>本地文件需要重新选择。</small>':`<a href="https://www.bilibili.com/video/BV1QS4y1e7y6/?t=${x.start}">打开原视频 ↗</a>`}`:''}${x.segment!==undefined?`<small>示例讲解 ${A.fmt(A.lecture[x.segment].time)}</small>`:''}</article>`).join('');const html=`<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Magic Note · ${e(p.title)}</title><style>body{max-width:950px;margin:40px auto;padding:0 24px;font:15px/1.9 system-ui;color:#18231b;background:#f7f8f4}h1{font-size:27px}h3{font-size:20px}img{max-width:100%;border:1px solid #dce5d4;border-radius:10px}article{padding:24px;background:white;border:1px solid #dce6d3;border-radius:12px;margin:25px 0}small,.document-top,.document-intent{color:#7e9072;font-size:12px}.document-equation{padding:25px;text-align:center;background:#f2f6ec;border-radius:8px}.document-equation>*{display:block}.document-equation strong{font:italic 28px Georgia,serif;padding:12px}.projection-figure svg{width:100%;height:180px}.projection-figure small{display:block;text-align:center}.document-source,.document-actions{font-size:11px;display:flex;gap:20px;padding-top:15px}p{white-space:pre-line}a{color:#235333}blockquote{border-left:2px solid #9bb486;padding-left:15px}blockquote span{display:block;color:#8ba079;font-size:12px}</style><h1>Magic Note / ${e(p.title)}</h1><small>demo · ${new Date().toLocaleDateString('zh-CN')}</small><h2>我的原稿</h2><img src="${ink}" alt="我的手写原稿"><p>${e(p.text)}</p>${enhanced}${cards}<footer><small>原稿完整保留。PCA 增强为交互示例；上传讲义内容为原文摘录。</small></footer></html>`;A.download(new Blob([html],{type:'text/html;charset=utf-8'}),'demo-Magic-Note.html');A.notify('已导出 Magic Note，包含原稿、增强笔记和保存的学习内容。');}
